def old(d, prefix, skills):
    src = {l["id"]: l["src"][0] for l in LESSONS345}
    return [dict(id=prefix + q["id"], type="single", skill=skills[q["lesson"]], stem=q["stem"], options=q["options"], answer=q["answer"],
                 runner=q["runner"], runnerWhy=q["runnerWhy"], think=q["think"], eli5=q["eli5"], learn=src[q["lesson"]])
            for q in QUESTIONS345 if q["d"] == d]

