GOAL = ("An insurer receives photos of damaged vehicles. Each photo must produce structured fields (damaged part, severity, visible registration) with confidence scores, "
        "and any text in the photo must not be able to change the agent's behaviour. **Goal:** meet both requirements with generally available features.")
def SOL(i, sol, ans, prem, apply, rule):
    return dict(id="d3-s" + str(i), type="solution", skill=S if i == 2 else U, scenario=GOAL, stem="**Proposed solution:** " + sol + " Does this meet the goal?", answer=ans,
                think=T(prem, [["Fields with confidence","Analyzer","Content Understanding field schema"],["Text inside images","Indirect attack","Prompt Shields at tool response"],["New build","Retired","Image Analysis custom models"]],
                        apply, rule, "Analyze images and video by using multimodal models and Content Understanding."),
                eli5="Fill in the form from the photo, and treat any note in the photo as evidence, not orders.", learn=AS+"content-understanding/overview")
